import "server-only";

/**
 * Server-side access to the card deck.
 *
 * learn-cards.ts is generated by the slwlrnr-cards project and carries every
 * card's paid prose. `server-only` makes the build fail if this module — and
 * therefore the paid content — is ever imported into a client component.
 * Client components receive only the trimmed shapes produced here.
 */

import {
  LEARN_CARDS,
  cardBySlug,
  publicView,
  type LearnCard,
} from "@/data/learn-cards";

export type { LearnCard };

/** What the library grid needs — no prose. Safe to send to any client. */
export type CardSummary = Pick<
  LearnCard,
  | "id"
  | "slug"
  | "number"
  | "strand"
  | "strandName"
  | "colour"
  | "title"
  | "subtitle"
  | "access"
  | "image"
> & { artist: string; work: string; date: string };

export function cardSummaries(): CardSummary[] {
  return LEARN_CARDS.map((c) => ({
    id: c.id,
    slug: c.slug,
    number: c.number,
    strand: c.strand,
    strandName: c.strandName,
    colour: c.colour,
    title: c.title,
    subtitle: c.subtitle,
    access: c.access,
    image: c.image,
    artist: c.credit.artist,
    work: c.credit.work,
    date: c.credit.date,
  }));
}

export const deckCounts = () => ({
  total: LEARN_CARDS.length,
  free: LEARN_CARDS.filter((c) => c.access === "free").length,
  strands: new Set(LEARN_CARDS.map((c) => c.strand)).size,
});

/**
 * The card as this viewer may see it. Non-subscribers on a paid card get the
 * front, credit, invitation and the opening paragraph only — the rest is never
 * serialised to the page.
 */
export function viewFor(card: LearnCard, entitled: boolean) {
  const view = publicView(card, entitled);
  const locked = card.access === "paid" && !entitled;
  return {
    ...view,
    locked,
    essay: locked ? card.essay.slice(0, 1) : view.essay,
  };
}

export type CardView = ReturnType<typeof viewFor>;

/** "Pairs with SYSTEMS & CHANCE 01 · Rules You Agree To Obey" → linked card, if published. */
export function resolveCross(cross: string) {
  const m = cross.match(/^Pairs with (.+?) (\d{2}) · (.+)$/);
  if (!m) return { label: cross, card: null };
  const [, strandName, number, title] = m;
  const card =
    LEARN_CARDS.find((c) => c.strandName === strandName && c.number === number) ??
    null;
  return {
    label: `${strandName.charAt(0)}${strandName.slice(1).toLowerCase()} ${number} · ${title}`,
    card: card ? { slug: card.slug, title: card.title } : null,
  };
}

export function neighbours(slug: string) {
  const i = LEARN_CARDS.findIndex((c) => c.slug === slug);
  const pick = (c?: LearnCard) => (c ? { slug: c.slug, title: c.title } : null);
  return { prev: pick(LEARN_CARDS[i - 1]), next: pick(LEARN_CARDS[i + 1]) };
}

export { LEARN_CARDS, cardBySlug };
